    },
    {
      "indicator": "MM50",
      "reading": "10.6926",
      "interpretation": "Suporte imediato de médio prazo; preço acima, confirmando tendência média positiva."
    },
    {
      "indicator": "MM200",
      "reading": "9.3597",
      "interpretation": "Suporte estrutural de longo prazo, bem abaixo do preço atual — tendência de fundo ainda intacta."
    },
    {
      "indicator": "EMA9",
      "reading": "10.9722",
      "interpretation": "EMA9 > EMA21 (10.8900) — viés comprador de curtíssimo prazo, mas preço fechou abaixo da EMA9 (sinal de fraqueza momentânea)."
    },
    {
      "indicator": "EMA21",
      "reading": "10.8900",
