      "reading": "MACD 0.1196 / Signal 0.1598 / Hist -0.0402",
      "interpretation": "MACD positivo porém abaixo da linha de sinal (histograma negativo) — momentum de alta em desaceleração; recente cruzamento para baixo do sinal."
    },
    {
      "indicator": "RSI14",
      "reading": "49.8913",
      "interpretation": "RSI neutro (~50): sem condição de sobrecompra ou sobrevenda; confirma consolidação."
    },
    {
      "indicator": "Bollinger",
      "reading": "Lower 10.0411 / Mid 10.8820 / Upper 11.7229",
      "interpretation": "Preço próximo da média (BB_mid) e dentro das bandas; amplitude ~1.68 BRL indica volatilidade moderada."
    },
    {
      "indicator": "Volume",
      "reading": "3605535400",
      "interpretation": "Volume moderado, abaixo dos picos recentes (ex.: 18084182000 em 2025-10-29); não confirma rompimento."
    }
  ]
